<script setup>
import DateInput from '../components/DateInput.vue';
import {ref,computed,watch} from 'vue';import Icon from '../components/Icon.vue';import EmptyState from '../components/EmptyState.vue';
import {state,company,api,scope,useResource,rows,notify,changed,ask} from '../lib/workspace';import {money,date,dateTime,cents} from '../lib/format';
const postingInput=ref(null),input=ref(null),file=ref(null),preview=ref(null),busy=ref(false),error=ref(''),result=ref(null),bankAccount=ref(''),options=ref({date_format:'',encoding:'auto',delimiter:';',decimal_separator:'',thousands_separator:'auto',posting_date:''}),previewContext=ref(null),showOptions=ref(false),dragging=ref(false);
const {data:history,reload}=useResource(async()=>state.companyId?rows(await api(scope('/imports'))):[]);
const blocking=computed(()=>preview.value?.issues?.filter(i=>['error','fatal'].includes(i.severity))||[]);
watch(()=>[state.companyId,state.period],()=>{file.value=null;preview.value=null;result.value=null;error.value='';bankAccount.value='';});
function choose(f){if(!f)return;if(f.size>20*1024*1024){error.value='O arquivo deve ter até 20 MB.';return;}file.value=f;preview.value=null;result.value=null;error.value='';}
const encode=f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});
function readingOptions(){const o={...options.value};if(!o.posting_date)delete o.posting_date;if(!o.date_format)delete o.date_format;if(!o.decimal_separator)delete o.decimal_separator;if(o.thousands_separator==='auto')delete o.thousands_separator;return o;}
async function analyze(){if(!file.value)return;if(postingInput.value&&!postingInput.value.reportValidity()){error.value='Confira a data de escrituração no formato DD/MM/AAAA.';return;}const ctx={id:state.companyId,period:state.period,name:company.value?.trade_name||company.value?.name};busy.value=true;error.value='';try{const content=await encode(file.value);const data=await api(scope('/imports/preview',ctx.id),{method:'POST',body:{filename:file.value.name,content_base64:content,period:ctx.period,options:readingOptions(),bank_account:bankAccount.value}});if(ctx.id!==state.companyId||ctx.period!==state.period)return;preview.value=data;previewContext.value=ctx;await reload();}catch(e){if(ctx.id===state.companyId)error.value=e.message;}finally{busy.value=false;}}
async function confirm(){if(!preview.value||blocking.value.length)return;if(preview.value.transactions?.length&&!bankAccount.value.trim()){error.value='Identifique a conta bancária para importar o extrato.';return;}if(!await ask({title:'Confirmar importação?',message:`Os registros serão vinculados a ${previewContext.value.name}, na competência ${previewContext.value.period.split('-').reverse().join('/')}. Documentos fiscais continuarão pendentes de conferência.`,confirmLabel:'Importar registros'}))return;busy.value=true;error.value='';try{result.value=await api(scope(`/imports/${preview.value.id}/confirm`,previewContext.value.id),{method:'POST',body:{preview_hash:preview.value.preview_hash,bank_account:bankAccount.value}});changed();notify('Importação confirmada. Confira os registros antes de escriturar.');preview.value.status='confirmed';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function inspect(h){error.value='';try{preview.value=await api(scope(`/imports/${h.id}`));previewContext.value={id:state.companyId,name:company.value?.trade_name||company.value?.name,period:preview.value.period};bankAccount.value=preview.value.bank_account||preview.value.bank_account_hint||'';result.value=null;file.value=null;}catch(e){error.value=e.message;}}
function totalCents(d){if(d.total_cents!==undefined)return d.total_cents;return cents(d.total||'0.00')||0;}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">ENTRADA DE DADOS</div><h1>Importações</h1><p>Preserve os arquivos de origem e confira os registros antes de confirmar.</p></div><span class="badge neutral"><Icon name="shield" :size="14"/>Importação com prévia e histórico</span></header>
<div class="import-layout"><section class="panel upload-panel"><div class="panel-heading"><div><h2>Selecionar arquivo</h2><p>Empresa: {{company?.trade_name||company?.name}}</p></div><Icon name="import"/></div><div class="dropzone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="dragging=false;choose($event.dataTransfer.files[0])"><span class="upload-circle"><Icon :name="file?'filecheck':'import'" :size="28"/></span><strong>{{file?.name||'Arraste o arquivo para esta área'}}</strong><span>{{file?`${(file.size/1024).toFixed(1)} KB · pronto para analisar`:'ou selecione no seu computador'}}</span><input ref="input" type="file" accept=".xml,.txt,.sped,.efd,.zip,.7z,.rar,.csv,.ofx,.qfx,.qif,.ofc" @change="choose($event.target.files[0])" aria-label="Selecionar arquivo de importação"/><button class="button outline" type="button" @click="input.click()" :disabled="busy">Selecionar arquivo</button><small>XML · SPED/TXT · ZIP / 7z / RAR · CSV · OFX · QIF · OFC<br>Limite de 20 MB por arquivo. Leiautes não reconhecidos geram pendência.</small></div><div class="upload-options"><button class="text-button" @click="showOptions=!showOptions"><Icon name="settings" :size="16"/>Opções de leitura e escrituração<Icon name="down" :size="15"/></button><div v-show="showOptions" class="form-grid three"><label>Formato da data<select v-model="options.date_format"><option value="">Padrão do formato</option><option value="DMY">Dia / mês / ano</option><option value="YMD">Ano / mês / dia</option><option value="MDY">Mês / dia / ano</option></select></label><label>Codificação<select v-model="options.encoding"><option value="auto">Detectar com conferência</option><option value="utf-8">UTF-8</option><option value="cp1252">Windows-1252</option></select></label><label>Separador<select v-model="options.delimiter"><option value=";">Ponto e vírgula</option><option value=",">Vírgula</option><option :value="'\t'">Tabulação</option></select></label><label>Separador decimal<select v-model="options.decimal_separator"><option value="">Padrão do formato</option><option value=",">Vírgula (1.234,56)</option><option value=".">Ponto (1,234.56)</option></select></label><label>Separador de milhares<select v-model="options.thousands_separator"><option value="auto">Padrão do formato</option><option value=".">Ponto</option><option value=",">Vírgula</option><option value="">Sem separador</option></select></label><label>Data de escrituração do XML<DateInput ref="postingInput" v-model="options.posting_date"/><small>Vazio: emissão proposta para conferência.</small></label><p class="field-help span-3">Layout bancário: cabeçalhos data, valor, historico e documento. Valores negativos representam saídas; positivos, entradas. Datas e valores ambíguos exigem configuração. Separe extratos com convenções numéricas diferentes em lotes distintos.</p></div><label>Conta bancária do extrato <small>Somente para importações financeiras.</small><input v-model="bankAccount" placeholder="Ex.: Banco / agência / conta"/></label></div><div v-if="error" class="message error" role="alert">{{error}}</div><div class="panel-action"><button class="button primary full" @click="analyze" :disabled="!file||busy"><Icon :name="busy?'loading':'search'"/>{{busy?'Processando arquivo...':'Analisar e gerar prévia'}}</button></div></section>
<section class="panel import-history"><div class="panel-heading"><div><h2>Histórico de arquivos</h2><p>Processamentos desta empresa.</p></div><span class="badge neutral">{{history.length}}</span></div><div v-if="history.length" class="history-list"><button v-for="h in history.slice().reverse()" :key="h.id" @click="inspect(h)"><span class="file-icon"><Icon name="file"/></span><span><strong>{{h.filename}}</strong><small>{{dateTime(h.created_at)}} · {{h.format||'Arquivo'}}</small></span><span class="badge" :class="h.status==='confirmed'?'success':'neutral'">{{h.status==='confirmed'?'Importado':'Prévia'}}</span></button></div><EmptyState v-else title="Nenhum arquivo processado" text="O histórico preservará origem, resultado e identificação de cada importação." icon="folder"/></section></div>
<section v-if="preview" class="panel preview-panel"><div class="panel-heading"><div><h2>Prévia · {{preview.filename}}</h2><p>{{previewContext?.name}} · {{preview.period.split('-').reverse().join('/')}} · {{preview.format}}</p></div><span class="badge" :class="blocking.length?'warning':preview.status==='confirmed'?'success':'info'">{{blocking.length?'Requer correção':preview.status==='confirmed'?'Importação confirmada':'Aguardando confirmação'}}</span></div><div class="summary-strip"><div><strong>{{preview.documents?.length||0}}</strong><span>documentos</span></div><div><strong>{{preview.transactions?.length||0}}</strong><span>movimentos bancários</span></div><div><strong>{{preview.issues?.length||0}}</strong><span>ocorrências</span></div><span class="push-right mono subtle">Origem SHA-256 {{preview.sha256?.slice(0,12)}}…</span></div><div v-if="preview.issues?.length" class="issues-list"><div v-for="(issue,i) in preview.issues" :key="i" class="message" :class="['error','fatal'].includes(issue.severity)?'error':'warning'"><Icon name="alert" :size="17"/><div><strong>{{issue.code}}</strong><span>{{issue.message}}</span></div></div></div>
<div v-if="preview.documents?.length" class="table-scroll preview-table"><table><thead><tr><th>Documento</th><th>Participante</th><th>Emissão</th><th>Operação</th><th class="right">Total</th></tr></thead><tbody><tr v-for="(d,i) in preview.documents" :key="i"><td class="mono">{{d.number}}</td><td>{{d.partner_name}}</td><td>{{date(d.issue_date)}}</td><td>{{d.direction==='incoming'?'Entrada':d.direction==='outgoing'?'Saída':'A conferir'}}</td><td class="right money">{{money(totalCents(d))}}</td></tr></tbody></table></div><div v-if="preview.transactions?.length" class="table-scroll preview-table"><table><thead><tr><th>Data</th><th>Histórico</th><th>Referência</th><th class="right">Valor</th></tr></thead><tbody><tr v-for="(t,i) in preview.transactions" :key="i"><td>{{date(t.date)}}</td><td>{{t.description}}</td><td class="mono">{{t.reference||t.external_id}}</td><td class="right money" :class="Number(t.amount)<0?'negative':'positive'">{{money(t.amount_cents??Math.round(Number(t.amount)*100))}}</td></tr></tbody></table></div><div v-if="result" class="message success"><Icon name="checks"/><span>{{result.documents_created||0}} documentos e {{result.transactions_created||0}} movimentos incluídos. {{(result.documents_duplicate||0)+(result.transactions_duplicate||0)}} registros já existentes preservados sem duplicação.</span></div><footer class="panel-action split"><span class="field-help">Confirmar a importação não aprova regras fiscais nem efetua baixas financeiras.</span><button v-if="preview.status!=='confirmed'" class="button primary" @click="confirm" :disabled="busy||blocking.length>0"><Icon :name="busy?'loading':'check'"/>Confirmar importação</button><button v-else class="button outline" @click="state.tab=preview.transactions?.length?'reconcile':'documents'">{{preview.transactions?.length?'Abrir conciliação':'Conferir documentos'}}<Icon name="arrow"/></button></footer></section>
</div></template>
